/**
 * .what = the text that marks a client file as the codegen's, or as already pointed at it
 * .why  = one text, two skips: a generated client and a client already marked both hold it.
 * .note = the codegen banner reads `generated by \`sdk-aws-lambda gen\``; the marker this module
 *         stamps names `npx sdk-aws-lambda gen`.
 */
const CODEGEN_MENTION = 'sdk-aws-lambda gen';

/**
 * .what = the stable token every marker this module stamps carries
 * .why  = the skip keys on this token too, so a reword of the marker's prose can never re-stamp a
 *         marked file — the fixed point does not rest on the codegen command's exact words alone
 */
const MARKER_TOKEN = 'declapract-typescript-ehmpathy#532';

/**
 * .what = is this file a hand-written client that wraps `askLambdaEndpoint`?
 * .why  = a hand-transcribed client drifts from its peer's contract in silence; the codegen emits
 *         one that matches the peer's live contract, so drift turns into a reviewable diff (#532)
 */
export const isAdhocLambdaClient = (input: { contents: string }): boolean =>
  /\baskLambdaEndpoint\b/.test(input.contents) &&
  !input.contents.includes(CODEGEN_MENTION) &&
  !input.contents.includes(MARKER_TOKEN);

/**
 * .what = the peer service slug a client file name spells, e.g. `svcJobs.ts` → `svc-jobs`
 * .why  = the marker names the exact codegen command for this peer, so the reader can paste it
 * .note = a name that spells no `svc*` peer yields a placeholder, never a guess
 */
const asPeerServiceSlug = (input: { relativeFilePath: string }): string => {
  const basename = input.relativeFilePath.split('/').pop() ?? '';
  const stem = basename.replace(/\.ts$/, '');
  if (!/^svc[A-Z]\w*$/.test(stem)) return '<svc-name>';
  return stem.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
};

/**
 * .what = stamp a review marker on line one that names the codegen for this peer
 * .why  = the move to a generated sdk changes the contract a caller imports (namespaced resources,
 *         `(event, context)` mechanisms), so it cannot be rewritten in place. the marker points the
 *         tree at the paved command rather than leave a hand-written client unflagged (#532).
 */
export const withLambdaClientGenMarker = (input: {
  contents: string;
  relativeFilePath: string;
}): string => {
  // skip a generated client, or one already marked
  if (!isAdhocLambdaClient({ contents: input.contents })) return input.contents;

  // name the paved command, for this peer
  const peer = asPeerServiceSlug({ relativeFilePath: input.relativeFilePath });
  const marker = `// @declapract:review — a hand-written lambda client drifts from its peer's contract; generate it via \`npx ${CODEGEN_MENTION} --for ${peer} --into src/access/svcs/ --env prep\`, move callers onto the generated sdk, then delete this file (${MARKER_TOKEN})`;
  return `${marker}\n${input.contents}`;
};
